it('passes session to onError and afterSession without running turn hooks when beforeSession throws', async () => {
  const initError = new Error('session setup failed');
  const laterHooks: string[] = [];
  let recordedError: {session: ChatSession; error: Error} | undefined;
  let closedSession: ChatSession | undefined;
  const session: ChatSession = {
    sessionId: 's-fail',
    userId: 'u1',
    entries: [{role: 'user', content: 'hello', timestamp: ''}],
  };
  const passThrough = (hookName: string) => async (_s: ChatSession, text: string) => {
    laterHooks.push(hookName);
    return text;
  };
  const engine = createHalEngine({
    ...base,
    orchestrator: {
      hooks: {
        beforeSession: async () => {
          throw initError;
        },
        beforeUserInput: passThrough('beforeUserInput'),
        afterUserInput: async () => void laterHooks.push('afterUserInput'),
        beforeModelResponse: passThrough('beforeModelResponse'),
        afterModelResponse: async () => void laterHooks.push('afterModelResponse'),
        onError: async (errSession, error) => {
          recordedError = {session: errSession, error};
        },
        afterSession: async endSession => {
          closedSession = endSession;
        },
      },
    },
  });

  const outcome = await engine.orchestrator.processMessage(session).catch((err: Error) => err.message);

  expect({
    outcome,
    sameOnErrorSession: recordedError?.session === session,
    sameError: recordedError?.error === initError,
    sameAfterSession: closedSession === session,
    laterHooks,
  }).toEqual({
    outcome: 'session setup failed',
    sameOnErrorSession: true,
    sameError: true,
    sameAfterSession: true,
    laterHooks: [],
  });
});
